import os, json, requests, time
os.environ['GALAXY_API_KEY'] = '[REDACTED_GALAXY_API_KEY]'

api_key = '[REDACTED_GALAXY_API_KEY]'
base_url = 'https://usegalaxy.org'
history_id = 'bbd44e69cb8906b503a49c4ebaf89247'
tool_id = 'toolshed.g2.bx.psu.edu/repos/ufz/xlsx2tsv/xlsx2tsv/0.2.0+galaxy0'

headers = {'x-api-key': api_key}

# Submit all 86 jobs individually without waiting
contents_r = requests.get(f'{base_url}/api/histories/{history_id}/contents', headers=headers)
contents = contents_r.json()

exome_ds = []
for item in contents:
    if item.get('extension') == 'xlsx' and item.get('state') == 'ok':
        name = item.get('name', '')
        if name.startswith('230209_Exome'):
            exome_ds.append(item['id'])

print(f"Found {len(exome_ds)} exome datasets to convert")

# Submit all jobs
job_ids = []
for i, ds_id in enumerate(exome_ds):
    payload = {
        'history_id': history_id,
        'tool_id': tool_id,
        'inputs': json.dumps({
            'input_file': {
                'src': 'hda',
                'id': ds_id
            }
        }),
        'input_format': '21.01'
    }

    r = requests.post(f'{base_url}/api/tools', data=payload, headers=headers)
    if r.status_code == 200:
        result = r.json()
        if 'jobs' in result:
            for job in result['jobs']:
                job_ids.append(job['id'])
        elif 'outputs' in result:
            # Direct output - already done
            pass

    if (i + 1) % 20 == 0:
        print(f"  Submitted {i+1}/{len(exome_ds)} jobs...")

print(f"\nSubmitted {len(job_ids)} jobs total")
print(f"Sample job IDs: {job_ids[:5]}")

# Now wait for all to complete
print("\nWaiting for jobs to complete...")
pending_ids = set(job_ids)
completed = 0
max_wait = 600
for attempt in range(max_wait // 10):
    for job_id in list(pending_ids):
        r = requests.get(f'{base_url}/api/jobs/{job_id}', headers=headers)
        if r.status_code == 200:
            job = r.json()
            state = job.get('state', '')
            if state in ('ok', 'error', 'failed', 'deleted'):
                pending_ids.discard(job_id)
                completed += 1

    if not pending_ids:
        print(f"All {completed} jobs completed!")
        break

    if attempt % 5 == 0:
        print(f"  {len(pending_ids)} jobs still pending, {completed} completed")

    time.sleep(10)
else:
    print(f"Timeout: {len(pending_ids)} jobs still pending")

# Count states
states = {}
for job_id in job_ids:
    r = requests.get(f'{base_url}/api/jobs/{job_id}', headers=headers)
    if r.status_code == 200:
        state = r.json().get('state', 'unknown')
        states[state] = states.get(state, 0) + 1
print(f"\nJob states: {states}")
EOF

