import os, requests, re
os.environ['GALAXY_API_KEY'] = '[REDACTED_GALAXY_API_KEY]'

api_key = '[REDACTED_GALAXY_API_KEY]'
base_url = 'https://usegalaxy.org'
history_id = 'bbd44e69cb8906b503a49c4ebaf89247'
headers = {'x-api-key': api_key}

r = requests.get(f'{base_url}/api/histories/{history_id}/contents', headers=headers)
contents = r.json()

# Map tabular outputs to their source xlsx files
# The tabular outputs are named "(Variants N) Filter Variants" 
# We need to find which xlsx each came from

# First, let's find the relationship by looking at jobs
# Get all jobs for this history
r_jobs = requests.get(f'{base_url}/api/jobs', headers=headers,
                       params={'history_id': history_id, 'limit': 500})
jobs = r_jobs.json()
print(f"Total jobs: {len(jobs)}")

# Find Excel to Tabular jobs and map input -> output
xlsx_to_tabular = {}
for job in jobs:
    if 'xlsx2tsv' in job.get('tool_id', ''):
        job_id = job['id']
        # Get job details
        r_job = requests.get(f'{base_url}/api/jobs/{job_id}', headers=headers, params={'full': 'true'})
        if r_job.status_code == 200:
            job_detail = r_job.json()
            inputs = job_detail.get('inputs', {})
            outputs = job_detail.get('outputs', {})
            input_file = inputs.get('input_file', {})
            if input_file and outputs:
                input_id = input_file.get('id', '')
                for out_name, out_info in outputs.items():
                    if isinstance(out_info, dict):
                        output_id = out_info.get('id', '')
                        if output_id:
                            if input_id not in xlsx_to_tabular:
                                xlsx_to_tabular[input_id] = []
                            xlsx_to_tabular[input_id].append(output_id)

print(f"Input xlsx -> output tabular mappings: {len(xlsx_to_tabular)}")

# Now find unique xlsx inputs (by individual name)
# Get xlsx dataset names
xlsx_names = {}
for item in contents:
    if item.get('extension') == 'xlsx' and item.get('state') == 'ok':
        name = item.get('name', '')
        if name.startswith('230209_Exome'):
            xlsx_names[item['id']] = name

# Group by individual (extract individual ID from filename)
# Pattern: 230209_Exome_GRCh38_CHIP_<ID>.xlsx
individuals = {}
for xlsx_id, name in xlsx_names.items():
    match = re.search(r'CHIP_([^.]++)', name)
    if match:
        ind_id = match.group(1)
        if ind_id not in individuals:
            individuals[ind_id] = []
        individuals[ind_id].append((xlsx_id, name))

print(f"\nUnique individuals: {len(individuals)}")
for ind_id, copies in list(individuals.items())[:5]:
    print(f"  {ind_id}: {len(copies)} copies")
    for xid, name in copies[:2]:
        print(f"    {name[:80]}... -> xlsx_id={xid[:30]}...")

# For each individual, pick one xlsx and find its tabular output
selected_tabular = []
for ind_id, copies in individuals.items():
    xlsx_id = copies[0][0]  # Take first copy
    if xlsx_id in xlsx_to_tabular:
        for tab_id in xlsx_to_tabular[xlsx_id]:
            selected_tabular.append(tab_id)

print(f"\nSelected tabular outputs (one per individual): {len(selected_tabular)}")
