                coding_vaf_lt_03_breakdown[so_term] = coding_vaf_lt_03_breakdown.get(so_term, 0) + 1
                if so_term == 'synonymous_variant':
                    synonymous_coding_vaf_lt_03 += 1

    except Exception as e:
        print(f"  Error on file {i}: {e}")

print(f"\n=== FINAL RESULTS ===")
print(f"Total variants across cohort: {all_variants_count}")
print(f"Total coding variants: {coding_all}")
print(f"Coding variants with empty VAF: {vaf_empty_coding}")
print(f"Coding variants with VAF < 0.3: {total_coding_vaf_lt_03}")
print(f"  Breakdown by SO term:")
for term, count in sorted(coding_vaf_lt_03_breakdown.items(), key=lambda x: -x[1]):
    print(f"    {term}: {count}")
print(f"Of those, synonymous_variant: {synonymous_coding_vaf_lt_03}")

if total_coding_vaf_lt_03 > 0:
    fraction = synonymous_coding_vaf_lt_03 / total_coding_vaf_lt_03
    print(f"\nFraction: {fraction}")
    print(f"Decimal: {fraction:.10f}")
else:
    print("\nNo coding variants with VAF < 0.3 found")
